@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Carbon (Concept 002) : silver-frosted glass on dark slate, photo-as-content vibe */

  --background: oklch(0.3032 0.0089 285.86);
  --foreground: oklch(0.9707 0.0027 286.35);

  /* Frosted-glass surface : Figma "7F7F7F @ 70%" extracted from the Concept 2 card.
     Card and primary CTA both use this exact fill on top of the dark slate bg. */
  --card: oklch(0.5624 0 0 / 0.7);
  --card-foreground: oklch(0.9707 0.0027 286.35);

  --popover: oklch(0.5624 0 0 / 0.85);
  --popover-foreground: oklch(0.9707 0.0027 286.35);

  /* Primary CTA pill = same silver frost as the card (the "add to your garage" pebble) */
  --primary: oklch(0.5624 0 0 / 0.7);
  --primary-foreground: oklch(0.9707 0.0027 286.35);

  --secondary: oklch(1 0 0 / 0.06);
  --secondary-foreground: oklch(0.9707 0.0027 286.35);

  --muted: oklch(1 0 0 / 0.05);
  --muted-foreground: oklch(0.8141 0 0);

  --accent: oklch(0.5624 0 0 / 0.5);
  --accent-foreground: oklch(0.9707 0.0027 286.35);

  --destructive: oklch(0.6756 0.2131 19.83);
  --destructive-foreground: oklch(0.9707 0.0027 286.35);

  --border: oklch(1 0 0 / 0.22);
  --input: oklch(0.5624 0 0 / 0.5);
  --ring: oklch(0.9707 0.0027 286.35 / 0.5);

  --radius: 1.5rem; /* 1.5rem : matches Concept 2's heavy card radius */

  /* Glass blur values lifted directly from Figma layer effects */
  --glass-backdrop-blur: 1.5rem;
  --glass-halo-blur: 7.5rem;

  /* Icon-chip token : light cream-gray square holding the "+" glyph inside CTA (Figma C2C2C2 @ 100%) */
  --icon-chip: oklch(0.8141 0 0);
  --icon-chip-foreground: oklch(0.3032 0.0089 285.86);

  /* Additional Figma highlight stops (white @ 20% and @ 10%) for rim lights / strokes */
  --highlight-strong: oklch(1 0 0 / 0.2);
  --highlight-soft: oklch(1 0 0 / 0.1);

  /* Overlay surface tokens : used by every floating slot (popover/dropdown/dialog/etc.).
     Centralised so the frosted look is editable from one place. */
  --overlay-fill: oklch(0.3581 0.0085 285.96 / 0.78);
  --overlay-border: oklch(1 0 0 / 0.22);
  --overlay-rim: oklch(1 0 0 / 0.16);
  --overlay-foreground: oklch(0.9707 0.0027 286.35);
  --overlay-blur: 0.5rem;
  --overlay-saturate: 1.5;
  --shadow-overlay:
    inset 0 0.0625rem 0 0 var(--overlay-rim),
    0 1rem 2.25rem -0.5rem oklch(0 0 0 / 0.55);

  /* Frosted-glass surface tokens : Figma inner-shadow (0,4,16 white@10%) +
     hairline white@20% top-rim stroke + soft ground shadow.
     Together these reproduce the "rim light hitting glass" effect from Concept 2. */
  --shadow-glass-card:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.2),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.1),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3),
    0 1rem 2.25rem -0.5rem oklch(0 0 0 / 0.45);
  --shadow-glass-card-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.24),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.14),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.35),
    0 1.5rem 3rem -0.5rem oklch(0 0 0 / 0.55);

  /* Primary CTA pebble : same Figma recipe applied to the pill */
  --shadow-pillow-primary:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.2),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.1),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3),
    0 0.5rem 1.25rem -0.25rem oklch(0 0 0 / 0.4);
  --shadow-pillow-primary-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.24),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.14),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.35),
    0 0.875rem 1.875rem -0.25rem oklch(0 0 0 / 0.5);

  /* Secondary glass pebble : same Figma recipe as primary, just on a darker base fill */
  --shadow-pillow-secondary:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.2),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.1),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3),
    0 0.375rem 1rem -0.25rem oklch(0 0 0 / 0.4);
  --shadow-pillow-secondary-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.24),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.14),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.35),
    0 0.625rem 1.5rem -0.25rem oklch(0 0 0 / 0.5);

  /* Destructive : same Figma inner-shadow recipe as primary, w/ a soft red bloom underneath */
  --shadow-pillow-destructive:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.2),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.1),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3),
    0 0.5rem 1.25rem -0.25rem color-mix(in oklch, var(--destructive) 40%, transparent);
  --shadow-pillow-destructive-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.24),
    inset 0 0.25rem 1rem oklch(1 0 0 / 0.14),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.35),
    0 0.875rem 1.875rem -0.25rem color-mix(in oklch, var(--destructive) 55%, transparent);

  /* Input : dark translucent field with hairline ring; focus = white ring */
  --shadow-input:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.06),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.08),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3);
  --shadow-input-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.08),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.14),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.35);
  --shadow-input-focus:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.1),
    0 0 0 0.125rem var(--ring),
    0 0.25rem 0.75rem -0.125rem oklch(0 0 0 / 0.5);

  /* Generic elevation : smoked, layered */
  --shadow-2xs: 0 0.0625rem 0.0625rem oklch(0 0 0 / 0.3);
  --shadow-xs:  0 0.0625rem 0.125rem oklch(0 0 0 / 0.35);
  --shadow-sm:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.06),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.35),
    0 0.125rem 0.375rem oklch(0 0 0 / 0.3);
  --shadow:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.06),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.4),
    0 0.5rem 1.25rem oklch(0 0 0 / 0.45);
  --shadow-md:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.08),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.45),
    0 0.75rem 1.75rem -0.25rem oklch(0 0 0 / 0.55);
  --shadow-lg:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.1),
    0 0.25rem 0.75rem oklch(0 0 0 / 0.5),
    0 1.5rem 3rem -0.375rem oklch(0 0 0 / 0.65);
  --shadow-xl:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.12),
    0 0.5rem 1.5rem oklch(0 0 0 / 0.55),
    0 0 0 0.0625rem oklch(1 0 0 / 0.06);

  /* ─── Chart palette: tonal ramp of the DS primary (one hue, five shades) ─── */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l - 0.09) calc(c * 0.92) h);
  --chart-3: oklch(from var(--primary) calc(l - 0.18) calc(c * 0.84) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.27) calc(c * 0.76) h);
  --chart-5: oklch(from var(--primary) calc(l - 0.36) calc(c * 0.68) h);

  /* --- Motion (soft profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.625rem);
  --radius-md: calc(var(--radius) - 0.375rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.5rem);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    letter-spacing: -0.014em;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* Let textareas grow with their content instead of nested scrolling:
     smoother writing, easier-to-scan forms. */
  textarea {
    /* Fallback for browsers without field-sizing (e.g. Firefox): keep the
       textarea user-resizable so it can still be grown manually. */
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: spacious;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 62);
  --layout-inset: calc(var(--spacing, 0.25rem) * 10);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 12);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 6);
}

